const DT = 1;
const LARGO_CAMPO = 105;
const ANCHO_CAMPO = 68;
const PORTERIA_X = 0;

const ACELERACION_MAX = 2.0;  //m/s2
const FRENADA_MAX = 3.0;      //m/s2
const GIRO_MAX = 90;          //grados por segundo
const PULSO_BASE = 90;        //bpm, valor inicial orientativo
const LONGITUD_PASO = 0.75;   //metros por apoyo, aproximacion

const aleatorio = (min, max) => min + Math.random() * (max - min);
const limitar = (v, min, max) => Math.max(min, Math.min(max, v));
const normalizarAngulo = a => ((a + 540) % 360) - 180;

//Un unico estado alimenta a los cinco sensores.
let s = context.get("estado") || {
    x: 4,
    y: 34,
    vx: 0,
    vy: 0,
    distancia: 0,
    modo: "parado",
    segundos: 0,
    objetivoX: 4,
    objetivoY: 34,
    velocidadObjetivo: 0,
    angulo: 0,
    carga: 0,
    pulso: PULSO_BASE,
    fasePaso: 0
};

if (!Number.isFinite(s.angulo)) s.angulo = 0;
if (!Number.isFinite(s.carga)) s.carga = 0;
if (!Number.isFinite(s.pulso)) s.pulso = PULSO_BASE;
if (!Number.isFinite(s.fasePaso)) s.fasePaso = 0;

//Elegir comportamiento del portero.
if (s.segundos <= 0) {
    const p = Math.random();
    s.modo = s.x > 9 ? "volver" :
        p < 0.50 ? "parado" :
            p < 0.80 ? "lateral" :
                p < 0.95 ? "recolocar" : "salida";

    switch (s.modo) {
        case "parado":
            s.objetivoX = s.x;
            s.objetivoY = s.y;
            s.velocidadObjetivo = 0;
            s.segundos = Math.ceil(aleatorio(2, 8));
            break;

        case "lateral":
            s.objetivoX = aleatorio(2, 6);
            s.objetivoY = aleatorio(29, 39);
            s.velocidadObjetivo = aleatorio(3, 8);
            s.segundos = Math.ceil(aleatorio(2, 5));
            break;

        case "recolocar":
            s.objetivoX = aleatorio(2, 9);
            s.objetivoY = aleatorio(26, 42);
            s.velocidadObjetivo = aleatorio(4, 10);
            s.segundos = Math.ceil(aleatorio(2, 6));
            break;

        case "salida":
            s.objetivoX = aleatorio(12, 20);
            s.objetivoY = aleatorio(23, 45);
            s.velocidadObjetivo = aleatorio(12, 22);
            s.segundos = Math.ceil(aleatorio(3, 6));
            break;

        case "volver":
            s.objetivoX = aleatorio(2, 6);
            s.objetivoY = aleatorio(30, 38);
            s.velocidadObjetivo = aleatorio(8, 16);
            s.segundos = 8;
            break;
    }
}

//GPS: calcular desplazamiento y velocidad.
const dx = s.objetivoX - s.x;
const dy = s.objetivoY - s.y;
const distanciaObjetivo = Math.hypot(dx, dy);
const velocidadAnterior = Math.hypot(s.vx, s.vy);
const velocidadDeseada = Math.min(
    s.velocidadObjetivo / 3.6,
    Math.sqrt(2 * FRENADA_MAX * distanciaObjetivo)
);

const vxDeseada = distanciaObjetivo > 0.001
    ? dx / distanciaObjetivo * velocidadDeseada : 0;

const vyDeseada = distanciaObjetivo > 0.001
    ? dy / distanciaObjetivo * velocidadDeseada : 0;

const dvx = vxDeseada - s.vx;
const dvy = vyDeseada - s.vy;

const cambioVector = Math.hypot(dvx, dvy);

const limite = velocidadDeseada < velocidadAnterior
    ? FRENADA_MAX : ACELERACION_MAX;

const factor = cambioVector > 0
    ? Math.min(1, limite * DT / cambioVector) : 0;

s.vx += dvx * factor;
s.vy += dvy * factor;

const xAnterior = s.x;
const yAnterior = s.y;

s.x = limitar(s.x + s.vx * DT, 0, LARGO_CAMPO);
s.y = limitar(s.y + s.vy * DT, 0, ANCHO_CAMPO);

s.vx = (s.x - xAnterior) / DT;
s.vy = (s.y - yAnterior) / DT;

const velocidadActual = Math.hypot(s.vx, s.vy);

const desplazamiento = Math.hypot(s.x - xAnterior, s.y - yAnterior);

s.distancia += desplazamiento;

//Acelerometro: cambios de rapidez entre lecturas.
const deltaRapidez = (velocidadActual - velocidadAnterior) / DT;
const aceleracion = Math.max(0, deltaRapidez);
const desaceleracion = Math.max(0, -deltaRapidez);

//Giroscopio: variacion de orientacion por segundo.
let anguloObjetivo = s.angulo;

if (velocidadActual > 0.25) {
    anguloObjetivo = Math.atan2(s.vy, s.vx) * 180 / Math.PI;
} else if (s.modo !== "parado" && distanciaObjetivo > 0.3) {
    anguloObjetivo = Math.atan2(dy, dx) * 180 / Math.PI;
}

const giro = limitar(
    normalizarAngulo(anguloObjetivo - s.angulo),
    -GIRO_MAX * DT, GIRO_MAX * DT);

s.angulo = normalizarAngulo(s.angulo + giro);

//Pulsometro: esfuerzo acumulado, respuesta lenta y recuperacion.
//La intensidad depende de velocidad y de aceleraciones positivas.
const intensidad = limitar(
    0.8 * limitar(velocidadActual / 6.1, 0, 1) +
    0.2 * limitar(aceleracion / ACELERACION_MAX, 0, 1),
    0, 1
);

//La carga aumenta mas deprisa de lo que se disipa.
const alphaCarga = intensidad > s.carga ? 0.18 : 0.04;
s.carga += (intensidad - s.carga) * alphaCarga;

//Al aumentar la carga, sube el pulso objetivo (hasta ~170 bpm).
const pulsoObjetivo = PULSO_BASE + 80 * s.carga;
const alphaPulso = pulsoObjetivo > s.pulso ? 0.13 : 0.035;
const ruido = aleatorio(-0.25, 0.25);
s.pulso = limitar(
    s.pulso + (pulsoObjetivo - s.pulso) * alphaPulso + ruido,
    60, 180
);

//Sensor de presion: reparto porcentual de carga entre ambos pies.
//50/50 aproximadamente en reposo. Durante el desplazamiento,
//la carga alterna con las pisadas y se desplaza lateralmente.
//Es una distribucion relativa, NO presion absoluta en kPa.
const actividad = limitar(velocidadActual / 6.1, 0, 1);

//Cada 0.75 m de avance alterna el pie de apoyo.
s.fasePaso = (s.fasePaso + Math.PI * desplazamiento / LONGITUD_PASO)
    % (2 * Math.PI);
const repartoPorPisada = Math.sin(s.fasePaso) * 30 * Math.sqrt(actividad);

//Asumimos X hacia la derecha e Y hacia arriba en el campo.
const velocidadDerecha = PORTERIA_X === 0 ? -s.vy : s.vy;
const sesgoLateral = 10 * limitar(velocidadDerecha / 3, -1, 1);

//Ligera variacion de apoyo (incluido en reposo).
const ruidoApoyo = aleatorio(-1.5, 1.5);
const presionDerecha = Number(limitar(
    50 + repartoPorPisada + sesgoLateral + ruidoApoyo,
    5, 95
).toFixed(1));
const presionIzquierda = Number((100 - presionDerecha).toFixed(1));

//Guardar el estado actualizado.
s.segundos--;
if (s.modo !== "parado" &&
    Math.hypot(s.objetivoX - s.x, s.objetivoY - s.y) < 0.5 &&
    velocidadActual < 0.5) {
    s.segundos = 0;
}
context.set("estado", s);

const posicionX = PORTERIA_X === 0 ? s.x : LARGO_CAMPO - s.x;
const giroGlobal = PORTERIA_X === 0 ? giro : -giro;

//Cinco publicaciones MQTT
const mensajeGPS = {
    topic: "p1/sensors/gps",
    payload: {
        speed: { unit: "km/h", value: Number((velocidadActual * 3.6).toFixed(2)) },
        distancecovered: { unit: "m", value: Number(s.distancia.toFixed(2)) },
        position: {
            X: { unit: "m", value: Number(posicionX.toFixed(2)) },
            Y: { unit: "m", value: Number(s.y.toFixed(2)) }
        }
    }
};

const mensajeAcelerometro = {
    topic: "p1/sensors/accelerometer",
    payload: {
        acceleration: { unit: "m/s2", value: Number(aceleracion.toFixed(2)) },
        desacceleration: { unit: "m/s2", value: Number(desaceleracion.toFixed(2)) }
    }
};

const mensajeGiroscopio = {
    topic: "p1/sensors/giroscope",
    payload: {
        changeinposition: { unit: "degrees", value: Number(giroGlobal.toFixed(2)) }
    }
};

const mensajePulsometro = {
    topic: "p1/sensors/pulsemeter",
    payload: {
        pulse: { unit: "bpm", value: Math.round(s.pulso) }
    }
};

const mensajePresion = {
    topic: "p1/sensors/pressuresensor",
    payload: {
        pressureleftfoot: { unit: "%", value: presionIzquierda },
        pressurerightfoot: { unit: "%", value: presionDerecha }
    }
};

return [[
    mensajeGPS,
    mensajeAcelerometro,
    mensajeGiroscopio,
    mensajePulsometro,
    mensajePresion
]];

